AgentGuardPageOptionsSchema.extend({
  isBackgroundRefresh: z.boolean().optional(),
  start_time: z.string().datetime({ offset: true }).optional(),
  end_time: z.string().datetime({ offset: true }).optional(),
}).refine(
  (v) => !v.start_time || !v.end_time || Date.parse(v.start_time) <= Date.parse(v.end_time),
  {
    message: 'start_time must not follow end_time',
    path: ['end_time'],
  },
)

z
  .object({
    organisation_id: z.string().optional(),
    name: z.string().min(1).max(255),
    slug: z.string().max(255).regex(new RegExp('^[a-zA-Z0-9_-]+$')).optional(),
    description: z.string().max(1024).nullable().optional(),
    manager_type: z.union([
      z.literal('aws_sm'),
      z.literal('azure_kv'),
      z.literal('hashicorp_vault'),
    ]),
    auth_config: z.union([
      GatewayRequestAwsAccessKeyAuthConfigSchema,
      GatewayRequestAwsAssumedRoleAuthConfigSchema,
      GatewayRequestAwsServiceRoleAuthConfigSchema,
      GatewayRequestAzureEntraAuthConfigSchema,
      GatewayRequestAzureManagedAuthConfigSchema,
      GatewayRequestAzureDefaultAuthConfigSchema,
      GatewayRequestHashicorpTokenAuthConfigSchema,
      GatewayRequestHashicorpAppRoleAuthConfigSchema,
      GatewayRequestHashicorpKubernetesAuthConfigSchema,
    ]),
    secret_path: z.string().max(1024),
    secret_key: z.string().max(255).nullable().optional(),
    allow_all_workspaces: z.boolean().optional(),
    allowed_workspaces: z.array(z.string()).min(1).optional(),
    tags: z.object({}).catchall(z.string()).nullable().optional(),
  })
  .strict()
  .superRefine((value, ctx) => {
    if (value.allow_all_workspaces === true && value.allowed_workspaces !== undefined)
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['allowed_workspaces'],
        message: 'Cannot combine allowed_workspaces with allow_all_workspaces=true',
      });
    const config = value.auth_config;
    const matches =
      value.manager_type === 'aws_sm'
        ? 'aws_auth_type' in config
        : value.manager_type === 'azure_kv'
          ? 'azure_auth_mode' in config
          : 'vault_auth_type' in config;
    if (!matches)
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['auth_config'],
        message: 'Authentication configuration must match manager_type',
      });
  })

z
  .object({
    name: z.string().min(1).max(255).optional(),
    description: z.string().max(1024).nullable().optional(),
    auth_config: z.object({}).catchall(GatewayJsonValueSchema).optional(),
    secret_path: z.string().max(1024).optional(),
    secret_key: z.string().max(255).nullable().optional(),
    allow_all_workspaces: z.boolean().optional(),
    allowed_workspaces: z.array(z.string()).min(1).optional(),
    tags: z.object({}).catchall(z.string()).nullable().optional(),
  })
  .strict()
  .superRefine((value, ctx) => {
    if (value.allow_all_workspaces === true && value.allowed_workspaces !== undefined)
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['allowed_workspaces'],
        message: 'Cannot combine allowed_workspaces with allow_all_workspaces=true',
      });
    if (Object.keys(value).length === 0)
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'Provide at least one update field' });
  })

z
  .object({
    workspace_id: uuid,
    /** Optional upstream organisation scope; SCM still requires workspace_id. */
    organisation_id: numericId.optional(),
    name: nonEmptyString,
    target: z.enum(['llm', 'mcp_tools']).optional(),
    checks: z.array(GatewayGuardrailCheckSchema).min(1).optional(),
    actions: GatewayGuardrailActionsSchema.optional(),
  })
  .strict()
  .superRefine((body, context) => {
    if (body.target !== 'mcp_tools') {
      if (!body.checks)
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['checks'],
          message: 'LLM guardrails require checks',
        });
      if (!body.actions)
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['actions'],
          message: 'LLM guardrails require actions',
        });
    }
  })

nonEmptyObject(
  z
    .object({
      rotation_period: z.enum(['monthly', 'weekly']).nullable().optional(),
      next_rotation_at: dateTime.nullable().optional(),
      key_transition_period_ms: z.number().int().min(1_800_000).optional(),
    })
    .strict(),
).refine(
  (value) => value.rotation_period == null || value.next_rotation_at == null,
  'rotation_period and next_rotation_at are mutually exclusive',
)

z
  .object({
    profile_id: z.string().uuid().optional(),
    profile_name: z.string().max(MAX_AI_PROFILE_NAME_LENGTH).optional(),
  })
  .passthrough()
  .refine((d) => d.profile_id || d.profile_name, {
    message: 'Either profile_id or profile_name must be provided',
  })

z
  .object({
    metadata: ToolEventMetadataSchema.optional(),
    input: z.string().optional(),
    output: z.string().optional(),
  })
  .passthrough()
  .refine((value) => value.input !== undefined || value.output !== undefined, {
    message: 'A tool event requires input or output',
  })
